int puts(char *s){int i=0;while(s[i]){putchar(s[i]);i=i+1;}putchar('\n');return i+1;}int strcmp(char *a,char *b){int i=0;while(a[i]){if(a[i]-b[i]){return a[i]-b[i];}i=i+1;}return a[i]-b[i];}int main(int argc,char **argv){int i=0;char *p=0;if(argv[argc]){puts("bad sentinel");return 90;}puts("args:");while(i<argc){p=argv[i];puts(p);i=i+1;}if(argc<2){puts("need a choice");return 11;}if(strcmp(argv[1],"hello")){puts("different\nargument");return 23;}puts("hello matched");if('A'-65){return 91;}p="";if(p[0]){return 92;}p="a\0b";if(p[1]){return 93;}if(p[2]-'b'){return 94;}return 7;}